import limited_client as r, numpy as np
for cam, pts in [('corner3',[(261,242),(260,248),(173,207),(173,211)]),('corner4',[(239,374),(238,369),(128,321),(128,327)])]:
 o=r.observe(cam); K=o['intrinsic']; T=o['camera_to_world'];
 print(cam)
 for u,v in pts:
  d=float(o['depth_m'][v,u]); pix=np.array([u,v,1]); q=np.linalg.inv(K)@pix*d; w=T@np.r_[q,1]; print((u,v),d,w[:3])
PY

